import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

async function isTeamMember(supabase, rootTwinId: string, checkTwinId: string): Promise<boolean> {
  const { data } = await supabase.from("digital_twins").select("id, manager_id");
  const children = new Map<string, string[]>();
  for (const t of data ?? []) {
    if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  }
  const seen = new Set<string>();
  const stack = [rootTwinId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen.has(checkTwinId);
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHORIZED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, org_id, email")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHORIZED" }, 401);

  let body: { rec_id?: string; decision?: string; rationale?: string } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const recId = (body.rec_id ?? "").trim();
  const decision = body.decision ?? "";
  const rationale = String(body.rationale ?? "").trim();
  if (!recId || !["approve", "reject", "request_more_review", "dispatch", "complete"].includes(decision)) {
    return json({ error: "BAD_REQUEST", message: "rec_id and decision are required." }, 400);
  }
  if (rationale.length < 5) {
    return json({ error: "RATIONALE_REQUIRED", message: "A short written rationale is required before the state can change." }, 400);
  }

  const { data: rec, error: recErr } = await supabase
    .from("recommendations")
    .select("*")
    .eq("id", recId)
    .maybeSingle();
  if (recErr || !rec) return json({ error: "NOT_FOUND" }, 404);
  if (rec.org_id !== caller.org_id) return json({ error: "FORBIDDEN" }, 403);

  // RBAC: HR Exec may act on any; HR Partner on hr-signoff recs; Manager on
  // manager-signoff recs for their own team.
  let allowed = false;
  if (caller.role === "hr_executive") allowed = true;
  else if (caller.role === "hr_partner" && rec.required_signoff_role === "hr_executive") allowed = true;
  else if (caller.role === "manager" && rec.required_signoff_role === "manager" && rec.twin_id) {
    allowed = rec.twin_id === caller.id || (await isTeamMember(supabase, caller.id, rec.twin_id));
  }
  if (!allowed) return json({ error: "FORBIDDEN", message: "You are not the required sign-off role for this recommendation." }, 403);

  // Deterministic state machine.
  const transitions: Record<string, { from: string[]; to: string }> = {
    approve: { from: ["needs_review"], to: "approved" },
    reject: { from: ["needs_review"], to: "rejected" },
    request_more_review: { from: ["needs_review"], to: "needs_review" },
    dispatch: { from: ["approved"], to: "dispatched" },
    complete: { from: ["dispatched"], to: "completed" },
  };
  const t = transitions[decision];
  if (!t.from.includes(rec.status)) {
    return json({ error: "INVALID_TRANSITION", message: `Cannot ${decision} a recommendation in state ${rec.status}.` }, 400);
  }

  const now = new Date().toISOString();
  const audit = [
    ...(rec.audit_events ?? []),
    {
      actor: caller.email ?? uid,
      action: decision,
      rationale,
      before: rec.status,
      after: t.to,
      timestamp: now,
    },
  ];

  let effect: string | null = null;

  if (decision === "dispatch") {
    const cat = String(rec.category ?? "").toLowerCase();
    // Real, honest internal effects — never a fake external dispatch.
    if (cat.includes("mobility")) {
      // Flag the employee as under mobility review on their DigitalTwin.
      const { data: twin } = await supabase
        .from("digital_twins")
        .select("id, signals, audit_events, name")
        .eq("id", rec.twin_id)
        .maybeSingle();
      if (twin) {
        const signals = (twin.signals ?? []).filter((s: { type?: string }) => s.type !== "mobility_review");
        signals.push({ type: "mobility_review", value: true, note: rationale, since: now });
        await supabase
          .from("digital_twins")
          .update({
            signals,
            audit_events: [...(twin.audit_events ?? []), { actor: caller.email ?? uid, action: "under_mobility_review", note: rationale, timestamp: now }],
          })
          .eq("id", twin.id);
        effect = `mobility review flag set on ${twin.name}'s DigitalTwin`;
      }
    } else if (cat.includes("retention") || cat.includes("workforce_review")) {
      const { data: twin } = await supabase
        .from("digital_twins")
        .select("id, signals, audit_events, name")
        .eq("id", rec.twin_id)
        .maybeSingle();
      if (twin) {
        const signals = (twin.signals ?? []).filter((s: { type?: string }) => s.type !== "retention_intervention");
        signals.push({ type: "retention_intervention", value: true, note: rationale, since: now });
        await supabase
          .from("digital_twins")
          .update({
            signals,
            audit_events: [...(twin.audit_events ?? []), { actor: caller.email ?? uid, action: "retention_intervention_dispatched", note: rationale, timestamp: now }],
          })
          .eq("id", twin.id);
        effect = `retention intervention flagged on ${twin.name}'s DigitalTwin`;
      }
    } else if (cat.includes("onboarding") || cat.includes("replan")) {
      // Re-open the journey so the onboarding center replans + re-approves.
      const { data: journey } = await supabase
        .from("onboarding_journeys")
        .select("id, twin_id, status, audit_events")
        .eq("twin_id", rec.twin_id)
        .maybeSingle();
      if (journey) {
        await supabase
          .from("onboarding_journeys")
          .update({
            status: "draft",
            audit_events: [...(journey.audit_events ?? []), { actor: caller.email ?? uid, action: "replan_requested", note: rationale, timestamp: now }],
          })
          .eq("id", journey.id);
        effect = "onboarding journey re-opened for replanning";
      }
    } else {
      effect = "no person-state change (action recorded)";
    }
  }

  await supabase
    .from("recommendations")
    .update({
      status: t.to,
      reviewer_rationale: { last: rationale, by: caller.email ?? uid, at: now },
      audit_events: audit,
    })
    .eq("id", recId);

  return json({ ok: true, status: t.to, effect, rationale });
});
